def task_func(task_prompt: str) -> float:
    import re
    import ast
    m = re.search(r"```(?:python)?\n(.*?)```", task_prompt, re.DOTALL)
    c = m.group(1) if m else ""

    def _parse_code(code):
        for attempt in (code, code + "\n    pass\n", code.rstrip() + "\n    pass\n"):
            try:
                return ast.parse(attempt)
            except SyntaxError:
                continue
        return None

    tree = _parse_code(c)
    if tree is None:
        return 0.0
    fd = None
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            fd = node
            break
    return float(len(fd.args.args)) if fd else 0.0

def task_func(task_prompt: str) -> float:
    import re
    import ast
    m = re.search(r"```(?:python)?\n(.*?)```", task_prompt, re.DOTALL)
    t = task_prompt[:m.start()] if m else task_prompt
    c = m.group(1) if m else ""
    text_libs = set(re.findall(
        r"\b(pandas|numpy|scipy|sklearn|matplotlib|seaborn|requests|bs4|beautifulsoup|nltk|"
        r"flask|django|sqlite3|django|regex|json|csv|datetime|collections|itertools|random|"
        r"os|sys|re|math|statistics|hashlib|base64|urllib|smtplib|xml|yaml)\b", t, re.I))
    libs_code = set()
    try:
        tree = ast.parse(c)
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    libs_code.add(a.name.split(".")[0])
            elif isinstance(node, ast.ImportFrom) and node.module:
                libs_code.add(node.module.split(".")[0])
    except SyntaxError:
        pass
    return float(len(libs_code | text_libs))

